func blLine(wd *port.Cells, ln *port.Cells, et *port.Cells, b []byte, page int32, x int32, y int32, size int32) int32 {
	// One line on `page` from x at y: the words of b (split at spaces) in type of `size` (centipoints), a word 24/11 of the size wide and a word 28/11 of it apart, the line 100 taller than the type,
	// its baseline 200 above its bottom.
	var w0 int32 = evidence.WdCount(wd)
	var n int32 = port.BlobLen(b)
	var y1 int32 = y + (size + 100)
	var ww int32 = (size * 24) / 11
	var st int32 = (size * 28) / 11
	var s int32 = 0
	var k int32 = 0
	var i int32 = 0
	var xe int32 = x
	for k <= n {
		if (k == n) || (port.BlobU8(b, k) == 32) {
			if k > s {
				var ts int32 = port.CellsLen(et)
				var wx int32 = x + (i * st)
				var wx1 int32 = wx + ww
				model.TextAppendUtf8(et, b, s, k)
				var tl int32 = port.CellsLen(et) - ts
				var r int32 = evidence.WdNew(wd, page, wx, y, wx1, y1, wx, y1-200, wx1, y1-200, 0, 0, ts, tl, -1, -1, -1)
				evidence.WdSet(wd, r, evidence.WfSize(), size)
				evidence.WdSet(wd, r, evidence.WfFont(), 0)
				xe = wx1
				i += 1
			}
			s = k + 1
		}
		k += 1
	}
	evidence.LnNew(ln, page, x, y, xe, y1, x, y1-200, xe, y1-200, 0, 0, w0, evidence.WdCount(wd)-w0)
	return 0
}

