func blFind(nodes *port.Cells, kind int32, nth int32) int32 {
	// The nth node (from 0) of the kind, -1 when there are not so many.
	var n int32 = model.NodeCount(nodes)
	var i int32 = 0
	var seen int32 = 0
	for i < n {
		if model.NodeKind(nodes, i) == kind {
			if seen == nth {
				return i
			}
			seen += 1
		}
		i += 1
	}
	return -1
}

func blYes(n int32) int32 {
	if n >= 0 {
		return 1
	}
	return 0
}

func blOwn(nodes *port.Cells, text *port.Cells, n int32, b []byte) int32 {
	// 1 when node n's own text is the ASCII text b.
	var start int32 = model.NodeTextStart(nodes, n)
	var i int32 = 0
	if model.NodeTextLen(nodes, n) != port.BlobLen(b) {
		return 0
	}
	for i < port.BlobLen(b) {
		if port.CellsAt(text, start+i) != port.BlobU8(b, i) {
			return 0
		}
		i += 1
	}
	return 1
}

func TestAFootnoteDoesNotGoOnInTheBodyOfTheNextPage(emonT *testing.T) {
	var wd *port.Cells = port.NewCells()
	var ln *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var nodes *port.Cells = port.NewCells()
	var attrs *port.Cells = port.NewCells()
	var regions *port.Cells = port.NewCells()
	var text *port.Cells = port.NewCells()
	var pages *port.Cells = port.NewCells()
	// P12.7 (smoke B N1): page 1 ends with a footnote in 8 pt whose last line stops at a hyphen; page 2 begins with body type that does not begin with a capital's full stop. The next page's body was the
	// footnote's continuation (a hyphen, a line that reaches the edge, no full stop); a footnote's text goes on only in type of its own size.
	blLine(wd, ln, et, port.TextBlob("lorem ipsum dolor sit amet consectetur adipiscing elit sed do eiusmod tempor"), 1, 7200, 5000, 1100)
	blLine(wd, ln, et, port.TextBlob("lorem ipsum dolor sit amet consectetur adipiscing elit sed do eiusmod tempor"), 1, 7200, 6400, 1100)
	blLine(wd, ln, et, port.TextBlob("lorem ipsum dolor sit amet consectetur adipiscing elit sed do eiusmod tempor"), 1, 7200, 7800, 1100)
	blLine(wd, ln, et, port.TextBlob("lorem ipsum dolor sit amet consectetur adipiscing elit sed do eiusmod tempor"), 1, 7200, 9200, 1100)
	blLine(wd, ln, et, port.TextBlob("4 We note that in the literature and the usage of the model the bidirectional Trans-"), 1, 7200, 70000, 800)
	blLine(wd, ln, et, port.TextBlob("Input Output Representations To make BERT handle a variety of tasks our input is able"), 2, 7200, 5000, 1100)
	blLine(wd, ln, et, port.TextBlob("lorem ipsum dolor sit amet consectetur adipiscing elit sed do eiusmod tempor"), 2, 7200, 6400, 1100)
	blLine(wd, ln, et, port.TextBlob("former is often referred to as a transformer encoder"), 2, 7200, 70000, 800)
	blModel(wd, ln, et, 2, nodes, attrs, regions, text, pages)
	var note int32 = blFind(nodes, model.NkNote(), 0)
	var np int32 = model.NodeFirstChild(nodes, note)
	port.AssertEq(emonT, blYes(note), 1, "the small line with the marker 4 at the foot of page 1 is a footnote")
	port.AssertEq(emonT, blOwn(nodes, text, np, port.TextBlob("We note that in the literature and the usage of the model the bidirectional Trans-")), 1, "the footnote is its own line and not the next page's body")
}

func blBody(wd *port.Cells, ln *port.Cells, et *port.Cells, page int32) int32 {
	// Four lines of body type on the page from y 5000.
	blLine(wd, ln, et, port.TextBlob("lorem ipsum dolor sit amet consectetur adipiscing elit sed do eiusmod tempor"), page, 7200, 5000, 1100)
	blLine(wd, ln, et, port.TextBlob("lorem ipsum dolor sit amet consectetur adipiscing elit sed do eiusmod tempor"), page, 7200, 6400, 1100)
	blLine(wd, ln, et, port.TextBlob("lorem ipsum dolor sit amet consectetur adipiscing elit sed do eiusmod tempor"), page, 7200, 7800, 1100)
	blLine(wd, ln, et, port.TextBlob("lorem ipsum dolor sit amet consectetur adipiscing elit sed do eiusmod tempor"), page, 7200, 9200, 1100)
	return 0
}

