func blDue(tb *port.Cells, ln *port.Cells, l int32) int32 {
	// 1 when the table 0 is due before line l (`tb-due-for`), the line's baseline sum its order key.
	if table.TbDueFor(tb, 0, 1, evidence.LnGet(ln, l, evidence.LhBy0())+evidence.LnGet(ln, l, evidence.LhBy1()), ln, l) {
		return 1
	}
	return 0
}

func TestALabelBesideATableOfFieldsComesBeforeIt(emonT *testing.T) {
	var wd *port.Cells = port.NewCells()
	var ln *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var tb *port.Cells = port.NewCells()
	// P12.7 (smoke A N4): the 1120's column of boxes and line numbers (x 468 to 576, y 325.9 to 372) stands beside the labels of its rows, which end at x 338: a field comes after its label. A line to the left of
	// the table that begins in its height is written before it; one below it, or to the right of its left edge, is not (the table goes first, as ever).
	table.TbAdd(tb, 1, 46800, 32590, 57620, 37200, 0, 1000, 3, 3, 0, 0)
	blLine(wd, ln, et, port.TextBlob("13 Salaries and wages"), 1, 5590, 32590, 800)
	blLine(wd, ln, et, port.TextBlob("Repairs"), 1, 5590, 36000, 800)
	blLine(wd, ln, et, port.TextBlob("later text"), 1, 5590, 38000, 800)
	blLine(wd, ln, et, port.TextBlob("right of it"), 1, 50000, 32590, 800)
	port.AssertEq(emonT, blDue(tb, ln, 0), 0, "a label at the table's top, to its left: it comes first")
	port.AssertEq(emonT, blDue(tb, ln, 1), 0, "so does the label of its fourth row")
	port.AssertEq(emonT, blDue(tb, ln, 2), 1, "a line under the table: the table goes first")
	port.AssertEq(emonT, blDue(tb, ln, 3), 1, "a line at its top but to its right: the table goes first")
}

func TestARunningHeaderAndFooterAreNoCaptions(emonT *testing.T) {
	var wd *port.Cells = port.NewCells()
	var ln *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var nodes *port.Cells = port.NewCells()
	var attrs *port.Cells = port.NewCells()
	var regions *port.Cells = port.NewCells()
	var text *port.Cells = port.NewCells()
	var pages *port.Cells = port.NewCells()
	var wd2 *port.Cells = port.NewCells()
	var ln2 *port.Cells = port.NewCells()
	var et2 *port.Cells = port.NewCells()
	var nodes2 *port.Cells = port.NewCells()
	var attrs2 *port.Cells = port.NewCells()
	var regions2 *port.Cells = port.NewCells()
	var text2 *port.Cells = port.NewCells()
	var pages2 *port.Cells = port.NewCells()
	// P12.7 (smoke A N1): `Schedule 1 (Form 1040) 2025 Created 7/25/25` small at the foot of page 1 and `Schedule 1 (Form 1040) 2025` small at the head of page 2 are a keyword and a number in type smaller than
	// the body, which made each a caption (its label gone from the text, the second the caption of the table under it). The same label with the same words after it on two pages is the document's running text. The
	// control: the same line on one page only is a caption.
	blBody(wd, ln, et, 1)
	blLine(wd, ln, et, port.TextBlob("Schedule 1 (Form 1040) 2025 Created 7/25/25"), 1, 7200, 55500, 800)
	blLine(wd, ln, et, port.TextBlob("Schedule 1 (Form 1040) 2025"), 2, 7200, 3000, 800)
	blBody(wd, ln, et, 2)
	blModel(wd, ln, et, 2, nodes, attrs, regions, text, pages)
	port.AssertEq(emonT, blYes(blFind(nodes, model.NkCaption(), 0)), 0, "a running header and footer are no captions")
	blLine(wd2, ln2, et2, port.TextBlob("Schedule 1 (Form 1040) 2025"), 1, 7200, 3000, 800)
	blBody(wd2, ln2, et2, 1)
	blModel(wd2, ln2, et2, 1, nodes2, attrs2, regions2, text2, pages2)
	port.AssertEq(emonT, blYes(blFind(nodes2, model.NkCaption(), 0)), 1, "the same line on one page is a caption")
}

